'use strict';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY = 'predictfix-mobile-demo-v1';
const icons = {overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',tickets:'<path d="M8 4H5v17h14V4h-3M8 3h8v4H8zM8 12h8M8 16h5"/>',sources:'<path d="M4 4h6l2 2 2-2h6v15h-6l-2 2-2-2H4zM12 6v15M7 9h2M15 9h2M7 13h2M15 13h2"/>',cases:'<path d="M4 5h16v16H4zM8 3v4M16 3v4M8 12l3 3 5-6"/>',wrench:'<path d="M14 6l4 4 3-3a6 6 0 0 1-8 8l-7 7-4-4 7-7a6 6 0 0 1 8-8z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',alert:'<path d="M12 3L2 21h20zM12 9v5M12 17v1"/>',arrow:'<path d="M5 12h14M14 7l5 5-5 5"/>'};
const icon = n => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n] || icons.tickets}</svg>`;
const navs = [['overview','維修總覽'],['tickets','維修工單'],['sources','來源知識庫'],['cases','維修案例']];
const statuses = ['待核准來源','待指派','維修中','待主管審核','已完成'];
const plans = {
  atc: {label:'換刀卡住',alarm:'ATC-07',cert:'換刀機構維修',source:'PF-MAN-ATC-002',title:'刀庫與換刀機構 · 卡刀排查',version:'1.0',section:'§ 2–3',scope:'展示 CNC 機型；換刀卡住、特定刀位異常。',quote:'若僅特定刀位異常，應優先核對刀套定位與感測器訊號；完成排查後須記錄連續換刀復測結果。',steps:[['核對氣壓與訊號','記錄展示量測與刀庫定位訊號。'],['核對刀套與定位','記錄特定刀位的定位及感測器狀態。'],['確認修復項目','記錄調整結果與更換部件。']],accept:['定位訊號正常','連續換刀 10 次無卡住'],sample:['氣壓 0.48 MPa；展示定位訊號有間歇異常。','12 號刀套感測器位置偏移，已調整展示定位。','已重新固定感測器並記錄調整結果。']},
  spindle: {label:'主軸過熱',alarm:'E102',cert:'主軸維修',source:'PF-MAN-SPINDLE-001',title:'主軸異常 · 溫度與振動排查',version:'1.0',section:'§ 2–3',scope:'展示 CNC 機型；主軸過熱或振動異常。',quote:'排查應核對冷卻循環、潤滑與固定件；復測記錄須包含修復後溫度及振動量測。',steps:[['核對冷卻循環','記錄液位、濾網與循環狀態。'],['核對潤滑與固定件','記錄展示潤滑及固定件檢查結果。'],['記錄修復後量測','記錄展示溫度、振動與修復項目。']],accept:['溫度符合展示驗收條件','振動復測通過'],sample:['冷卻循環濾網堵塞，已清理展示濾網。','潤滑及固定件檢查正常。','展示復測溫度 42°C、振動 1.2 mm/s。']},
  coolant: {label:'冷卻異常',alarm:'COOL-02',cert:'冷卻系統維修',source:'PF-MAN-COOLANT-003',title:'冷卻系統 · 循環異常排查',version:'1.0',section:'§ 2–3',scope:'展示 CNC 機型；冷卻流量不足、泵浦異常。',quote:'核對冷卻液液位、濾網與循環泵狀態，完成處置後記錄流量與漏液復測。',steps:[['核對液位與濾網','記錄展示液位與濾網狀態。'],['核對循環泵與管路','記錄泵浦運轉、接頭及管路狀態。'],['記錄修復項目','記錄清潔、更換與補液結果。']],accept:['循環流量復測通過','管路無漏液'],sample:['展示液位偏低，濾網已清理。','循環泵運轉正常；管路無破損。','已補充展示冷卻液並重新確認循環。']}
};
const people = [
 {name:'陳怡安',initial:'陳',certs:['換刀機構維修','主軸維修','冷卻系統維修'],capacity:4,available:true,desc:'CNC 維修 · 換刀機構與主軸',role:true},
 {name:'王志明',initial:'王',certs:['冷卻系統維修'],capacity:5,available:true,desc:'冷卻與電控 · 尚無換刀／主軸資格'},
 {name:'李柏翰',initial:'李',certs:['換刀機構維修','主軸維修'],capacity:0,available:false,desc:'CNC 維修 · 今日未出勤'}
];
const engineerName = () => state.role === 'engineer-wang' ? '王志明' : '陳怡安';
const isEngineer = () => state.role === 'engineer' || state.role === 'engineer-wang';
const stamp = () => new Date().toLocaleString('zh-TW',{timeZone:'Asia/Taipei',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
function makeTicket(machine,issue,alarm,hours,conditions,plan='atc') {return {id:'WO-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,5).toUpperCase(),machine,issue,alarm,hours,conditions,plan,stage:0,engineer:null,checks:[false,false,false],notes:['','',''],accept:['',''],summary:'',review:'',published:false,history:[{text:'林組長建立報修工單',at:stamp()}],submissions:[]};}
function seed(){const t=makeTicket('CNC-03','換刀卡住，只發生在 12 號刀位','ATC-07',2,'其他刀位正常，氣壓 0.48 MPa。');t.id='WO-DEMO-003';return {version:1,tickets:[t],cases:[],role:'supervisor'};}
function validState(v){return v?.version===1 && ['supervisor','engineer','engineer-wang'].includes(v.role) && Array.isArray(v.tickets) && v.tickets.length<500 && Array.isArray(v.cases) && v.cases.every(c=>c&&typeof c.title==='string'&&typeof c.summary==='string') && v.tickets.every(t=>t&&typeof t.id==='string'&&typeof t.issue==='string'&&plans[t.plan]&&Number.isInteger(t.stage)&&t.stage>=0&&t.stage<=4&&Number.isFinite(t.hours)&&t.hours>0&&Array.isArray(t.checks)&&t.checks.length===3&&Array.isArray(t.notes)&&t.notes.length===3&&Array.isArray(t.accept)&&t.accept.length===2&&Array.isArray(t.history)&&Array.isArray(t.submissions));}
let state;try{const raw=JSON.parse(localStorage.getItem(KEY));state=validState(raw)?raw:seed();}catch{state=seed();}
let filter='全部',toastTimer,saveWarning=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{if(!saveWarning){saveWarning=true;toast('瀏覽器無法保存，資料將保留至關閉頁面。');}}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function log(t,text){t.history.push({text,at:stamp()});save();}
function activeTicket(){const id=decodeURIComponent(location.hash.split('/')[1] || '');return state.tickets.find(t=>t.id===id);}
function currentView(){return location.hash.slice(1).split('/')[0]||'overview';}
function goto(view){if(location.hash==='#'+view)render();else location.hash=view;}
function roleIs(role){if(role==='engineer'?!isEngineer():state.role!==role){toast('請先在右上角切換為'+(role==='supervisor'?'主管':'工程師')+'。');return false;}return true;}
function remaining(p,t){return p.capacity-state.tickets.filter(x=>x.id!==t.id&&x.engineer===p.name&&x.stage>=2&&x.stage<4).reduce((n,x)=>n+x.hours,0);}
function eligible(p,t){return p.available&&p.certs.includes(plans[t.plan].cert)&&remaining(p,t)>=t.hours;}
function statusBadge(t){return `<span class="badge ${t.stage===0||t.stage===1?'orange':t.stage===4?'lime':'blue'}">${statuses[t.stage]}</span>`;}
function navHTML(view){const active=view==='ticket'?'tickets':view;return navs.map(([id,name])=>`<a href="#${id}" class="nav-item ${id===active?'active':''}" ${id===active?'aria-current="page"':''}>${icon(id)}<span>${name}</span>${id==='tickets'?`<span class="nav-count">${state.tickets.filter(t=>t.stage<4).length}</span>`:''}</a>`).join('');}
function heading(title,subtitle,action=true){return `<div class="page-heading"><div><span class="eyebrow">PREDICTFIX WORKSPACE</span><h1>${title}</h1><p>${subtitle}</p></div>${action?'<div class="heading-actions"><button class="button primary" data-action="new">＋ 建立報修</button></div>':''}</div>`;}
function ticketRows(items){return items.map(t=>`<button class="ticket-row" data-ticket="${esc(t.id)}"><span class="row-icon">${icon('wrench')}</span><span class="row-copy"><b>${esc(t.issue)}</b><small>${esc(t.machine)} · ${esc(t.id)} · ${esc(t.engineer||'待指派')}</small></span>${statusBadge(t)}<span class="row-arrow">↗</span></button>`).join('')||'<div class="empty">目前沒有符合條件的工單。</div>';}
const scene=`<div class="machine-scene"><span class="machine-caption">CNC-03 / TOOL CHANGER</span><svg viewBox="0 0 420 280" role="img" aria-label="CNC 展示機台線框插圖"><defs><linearGradient id="body" x2="0" y2="1"><stop stop-color="#42616b"/><stop offset="1" stop-color="#213640"/></linearGradient><pattern id="grid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#87a7a3" stroke-opacity=".08"/></pattern></defs><rect width="420" height="280" fill="url(#grid)"/><ellipse cx="220" cy="252" rx="160" ry="20" fill="#091f26" opacity=".45"/><path d="M66 63l214-30 67 40v151l-227 36-54-41z" fill="url(#body)" stroke="#809ba3" stroke-width="1.5"/><path d="M66 63l54 34 227-24M120 97v163" fill="none" stroke="#7796a0"/><path d="M135 111l106-17v121l-106 17z" fill="#122830" stroke="#6a8792"/><path d="M143 118l90-15v102l-90 16z" fill="#1c3e47"/><path d="M173 128l29-4v30l-8 12v26l-14 2v-26l-7-7z" fill="#a4b7b0" stroke="#cfdbca"/><path d="M164 195l54-9v10l-54 9z" fill="#809890"/><path d="M155 207l70-11v6l-70 11z" fill="#556f6b"/><path d="M250 92l53-8v54l-53 9z" fill="#0e252d" stroke="#718e98"/><path d="M258 102l35-5v27l-35 5z" fill="#294a45"/><path d="M265 113l8-8 7 9 7-6" fill="none" stroke="#d2f580" stroke-width="2"/><g fill="#6a8690"><circle cx="260" cy="154" r="3"/><circle cx="273" cy="152" r="3"/><circle cx="286" cy="150" r="3"/></g><circle cx="300" cy="164" r="5" fill="#ffb176"/><path d="M262 192l38-6M262 201l38-6M262 210l38-6" stroke="#536f7a"/><path d="M80 97l23 14v93l-23-14z" fill="#253e49" stroke="#4e6b76"/><path d="M104 222v-18" stroke="#d2f580" stroke-width="3"/><path d="M165 67l70-10" stroke="#bdd0c0" stroke-width="4"/><path d="M283 29v-11" stroke="#849c9b" stroke-width="3"/><rect x="278" y="8" width="10" height="12" rx="3" fill="#ffb176"/><circle cx="188" cy="147" r="30" fill="none" stroke="#d2f580" opacity=".6" stroke-dasharray="4 5"/><path d="M218 142h40l28 21" fill="none" stroke="#d2f580" opacity=".7"/><circle cx="188" cy="147" r="4" fill="#d2f580"/></svg><div class="machine-alert">${icon('alert')}<div>12 號刀位 · 換刀異常<small>ATC-07 / 虛構展示警報</small></div></div></div>`;
function overview(){const pending=state.tickets.filter(t=>t.stage<4).length;return heading('每一次維修，都有依據。','從異常到驗收，讓現場與主管保持同步。')+`<section class="stats" aria-label="展示統計"><div class="stat"><div class="stat-top">展示設備 ${icon('overview')}</div><div class="stat-value">03<small>台</small></div><div class="stat-foot">CNC 加工中心 · 虛構資料</div></div><div class="stat"><div class="stat-top">進行中工單 ${icon('tickets')}</div><div class="stat-value orange">${String(pending).padStart(2,'0')}<small>筆</small></div><div class="stat-foot">依此瀏覽器操作即時更新</div></div><div class="stat"><div class="stat-top">等待審核 ${icon('clock')}</div><div class="stat-value">${String(state.tickets.filter(t=>t.stage===3).length).padStart(2,'0')}<small>筆</small></div><div class="stat-foot">工程師已提交復測結果</div></div><div class="stat"><div class="stat-top">已完成工單 ${icon('cases')}</div><div class="stat-value lime">${String(state.tickets.filter(t=>t.stage===4).length).padStart(2,'0')}<small>筆</small></div><div class="stat-foot">由主管核對證據後結案</div></div></section><section class="hero"><div class="hero-copy"><span class="eyebrow">TRY THE COMPLETE WORKFLOW</span><h2>換刀卡住了。<br>下一步，<em>有跡可循。</em></h2><p>從 CNC-03 的換刀異常開始，核對手冊、找到合適工程師，再用復測結果完成驗收。</p><div class="hero-tags"><span class="tag">有來源的排查</span><span class="tag">資格與容量派工</span><span class="tag">有證據的驗收</span></div><button class="button primary" data-action="scenario">開始換刀卡住情境 ${icon('arrow')}</button></div>${scene}</section><div class="overview-grid"><section class="panel"><div class="panel-head"><h2>待處理的維修</h2><a class="text-button" href="#tickets">查看所有工單 ↗</a></div>${ticketRows(state.tickets.filter(t=>t.stage<4).slice(0,4))}</section><section class="panel"><div class="panel-head"><h2>一張工單，串起完整流程</h2><span class="badge">5 STEPS</span></div><ol class="mini-flow"><li><div><strong>報修與核對來源</strong>核對症狀、機型與引用原文</div></li><li><div><strong>核准清單與派工</strong>檢查資格、出勤及剩餘容量</div></li><li><div><strong>排查與復測</strong>逐項記錄，驗收通過才能提交</div></li><li><div><strong>主管審核</strong>核對證據，通過或退回重修</div></li><li><div><strong>累積維修案例</strong>人工發布，供下次核對</div></li></ol></section></div>`;}
function ticketsView(){const items=state.tickets.filter(t=>filter==='全部'||(filter==='進行中'?t.stage<3:filter==='待審核'?t.stage===3:t.stage===4));return heading('維修工單','追蹤每一張工單，從報修到留下維修案例。')+`<div class="filters" aria-label="工單篩選">${['全部','進行中','待審核','已完成'].map(f=>`<button class="filter ${f===filter?'active':''}" data-filter="${f}" aria-pressed="${f===filter}">${f}</button>`).join('')}</div><div class="panel ticket-list">${ticketRows(items)}</div>`;}
function sourceCard(p){return `<article class="source-card"><div class="source-top"><span>${esc(p.source)} · v${p.version}</span><span class="badge lime">示範手冊</span></div><h3>${p.title}</h3><p>${p.scope}</p><blockquote>${p.quote}</blockquote><button class="text-button" data-source="${Object.keys(plans).find(k=>plans[k]===p)}">核對來源原文 · ${p.section} ↗</button></article>`;}
function sourcesView(){return heading('來源知識庫','每一項排查建議，都能回到來源核對。',false)+`<input class="search-input" id="source-search" type="search" placeholder="搜尋換刀、主軸、冷卻或手冊編號…" aria-label="搜尋示範手冊"><div class="source-grid" id="source-results">${Object.values(plans).map(sourceCard).join('')}</div><div class="info-note">3 份原創示範手冊摘要；搜尋採本機字詞比對，未呼叫 LLM 或正式檢索服務。數值及處置僅供操作展示。</div>`;}
function casesView(){return heading('維修案例','把這次解決的問題，留給下一次維修。',false)+(state.cases.length?state.cases.map(c=>`<article class="case"><span class="badge lime">主管已發布</span><h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p><div class="case-meta">${esc(c.machine)} · 來源 ${esc(c.source)} · ${esc(c.at)} · ${esc(c.ticket)}</div></article>`).join(''):`<section class="panel empty">${icon('cases')}<h3 class="mobile-style-1">第一個案例，從一張工單開始。</h3><p>完成排查、驗收與主管審核後，<br>即可將維修結果發布為展示案例。</p><a href="#tickets" class="mobile-style-2 button primary">前往維修工單 →</a></section>`);}
function sourceStep(t,p){return `<section class="panel detail-section"><span class="eyebrow">01 / VERIFY & APPROVE</span><h2>先核對依據，再開始排查。</h2><p class="muted">固定情境比對找到以下展示來源，請主管確認適用性。</p>${sourceCard(p)}<div class="info-note">${esc(t.alarm)} · ${esc(t.conditions)}<br>必要資格：${p.cert} · 排查 ${p.steps.length} 項、驗收 ${p.accept.length} 項。</div><label class="check-line"><input type="checkbox" id="source-confirm"><span>我已核對來源、症狀與機型，核准這份展示排查及驗收清單。</span></label><button class="button primary full" data-action="approve" ${state.role==='supervisor'?'':'disabled'}>核准清單，選擇工程師 →</button>${isEngineer()?'<p class="info-note">請切換為主管，核准清單。</p>':''}</section>`;}
function assignStep(t,p){return `<section class="panel detail-section"><span class="eyebrow">02 / QUALIFIED ASSIGNMENT</span><h2>讓合適的人，處理這次異常。</h2><p class="muted">需要 ${p.cert} 資格，預估 ${t.hours} 小時。剩餘容量會扣除進行中的 demo 工單。</p>${people.map((person,i)=>{const ok=eligible(person,t),cert=person.certs.includes(p.cert),capacity=remaining(person,t);return `<article class="engineer-card ${ok?'recommended':''}"><div class="engineer-top"><span class="avatar">${person.initial}</span><div><h3>${person.name}</h3><small class="muted">${person.desc}</small></div><span class="badge ${ok?'lime':'orange'}">${ok?'可派工':'不可派工'}</span></div><p>${ok?'資格、出勤與容量符合；可切換為被指派的工程師操作。':!person.available?'今日未出勤，阻擋派工。':!cert?'缺少必要資格，阻擋派工。':'剩餘容量不足，阻擋派工。'}</p><div class="engineer-facts"><span class="${cert?'fact-good':'fact-bad'}">${cert?'✓ 資格符合':'× 資格不足'}</span><span class="${person.available?'fact-good':'fact-bad'}">${person.available?'✓ 今日出勤':'× 未出勤'}</span><span>剩餘 ${Math.max(0,capacity)} 小時</span></div><button class="button ${ok?'primary':'secondary'}" data-assign="${i}" ${ok&&state.role==='supervisor'?'':'disabled'}>指派 ${person.name}</button></article>`;}).join('')}</section>`;}
function executionStep(t,p){const can=isEngineer()&&t.engineer===engineerName();return `<section class="panel detail-section"><span class="eyebrow">03 / EXECUTE & VERIFY</span><h2>${t.rework?'重新排查，重新留下證據。':'把排查與復測，記錄在同一處。'}</h2><p class="muted">工程師 ${esc(t.engineer)} 執行；每一項排查需要紀錄，所有驗收通過才可提交。</p>${t.rework?`<div class="info-note warning">主管退回原因：${esc(t.review)}。前次提交仍保留在右側歷程中。</div>`:''}${!can?'<button class="mobile-style-3 button primary full" data-action="switch-engineer">切換為被指派的工程師</button>':'<button class="mobile-style-3 button secondary full" data-action="sample">填入示範排查紀錄</button>'}<form id="execution-form"><fieldset ${can?'':'disabled'} class="mobile-style-4">${p.steps.map((s,i)=>`<div class="task-item"><label class="check-line"><input type="checkbox" data-check="${i}" ${t.checks[i]?'checked':''}><span>${i+1}. ${s[0]}</span></label><p>${s[1]}</p><textarea rows="2" data-note="${i}" aria-label="${s[0]}紀錄" maxlength="600" placeholder="填寫檢查結果與量測…">${esc(t.notes[i])}</textarea></div>`).join('')}<h3 class="mobile-style-5">復測驗收</h3>${p.accept.map((a,i)=>`<label class="accept-row"><span>${a}<small>需明確記錄通過或失敗</small></span><select data-accept="${i}" aria-label="${a}"><option value="">未記錄</option><option value="pass" ${t.accept[i]==='pass'?'selected':''}>通過</option><option value="fail" ${t.accept[i]==='fail'?'selected':''}>失敗</option></select></label>`).join('')}<label>修復摘要<textarea id="summary" required minlength="5" maxlength="1000" rows="3" placeholder="填寫異常原因、處置與復測結果…">${esc(t.summary)}</textarea></label><div class="info-note ${t.accept.includes('fail')?'warning':''}" id="validation">${validationText(t)}</div><button class="mobile-style-3 button primary full" type="submit">提交復測結果，請主管審核 →</button></fieldset></form></section>`;}
function validationText(t){if(t.accept.includes('fail'))return '驗收失敗：請處理異常並重新復測，系統會阻擋提交。';return ready(t)?'排查與驗收已完成，可以提交主管審核。':'提交前需完成 3 項排查與紀錄、2 項驗收通過，以及至少 5 字的修復摘要。';}
function ready(t){return t.checks.every(Boolean)&&t.notes.every(n=>String(n).trim().length>=3)&&t.accept.every(a=>a==='pass')&&t.summary.trim().length>=5;}
function evidence(t,p){return `<div class="review-evidence">${p.steps.map((s,i)=>`<div>✓ ${s[0]}<small>${esc(t.notes[i])}</small></div>`).join('')}${p.accept.map(a=>`<div><span class="mobile-style-6">✓ ${a} · 通過</span></div>`).join('')}<div>修復摘要<small>${esc(t.summary)}</small></div></div>`;}
function reviewStep(t,p){return `<section class="panel detail-section"><span class="eyebrow">04 / SUPERVISOR REVIEW</span><h2>核對結果，再決定是否結案。</h2><p class="muted">提交人：${esc(t.engineer)} · 本次結果已保存提交快照。</p>${evidence(t,p)}${state.role!=='supervisor'?'<button class="mobile-style-7 button primary full" data-action="switch-supervisor">切換為主管 · 林組長</button>':`<label>審核意見（退回時必填）<textarea id="review-note" rows="2" maxlength="600" placeholder="通過意見，或需要重修的具體原因…"></textarea></label><div class="button-row"><button class="button secondary" data-action="return">退回重修</button><button class="button primary" data-action="complete">通過審核，結案 ✓</button></div>`}</section>`;}
function completeStep(t,p){return `<section class="panel detail-section"><div class="success-banner"><span class="eyebrow">WORK ORDER COMPLETED</span><h2>維修完成，經驗可以留下。</h2><p>主管已核對來源、排查及復測結果，這張工單已結案。</p></div>${evidence(t,p)}<div class="info-note">主管審核意見：${esc(t.review)}</div>${t.published?'<a class="mobile-style-7 button primary full" href="#cases">查看已發布案例 →</a>':`<label>案例標題<input id="case-title" value="${esc(t.machine+' · '+p.label+'排除案例')}" maxlength="120"></label><label>案例摘要<textarea id="case-summary" rows="4" maxlength="1400">${esc(t.summary)}</textarea></label><label class="check-line"><input id="case-confirm" type="checkbox"><span>主管已核對案例內容及來源，確認可發布為虛構展示案例。</span></label><button class="button primary full" data-action="publish" ${state.role==='supervisor'?'':'disabled'}>核對完成，發布案例 →</button>`}</section>`;}
function ticketView(t){if(!t)return heading('找不到這張工單','工單可能已重設。請返回工單清單。',false)+'<a class="button secondary" href="#tickets">返回工單</a>';const p=plans[t.plan];const stages=['核對來源','資格派工','排查驗收','主管審核','完成結案'];return `<a class="back" href="#tickets">← 返回工單清單</a><div class="page-heading"><div><span class="eyebrow">${esc(t.id)}</span><h1 class="ticket-title">${esc(t.issue)}</h1><div class="ticket-meta"><span>${esc(t.machine)} · ${esc(t.alarm)}</span><span>預估 ${t.hours} 小時</span>${statusBadge(t)}</div></div></div><ol class="progress" aria-label="工單進度">${stages.map((s,i)=>`<li class="${i<t.stage?'done':i===t.stage?'current':''}" ${i===t.stage?'aria-current="step"':''}><span class="step-num">${i<t.stage?'✓':i+1}</span>${s}</li>`).join('')}</ol><div class="detail-grid"><div>${[sourceStep,assignStep,executionStep,reviewStep,completeStep][t.stage](t,p)}</div><aside class="detail-aside"><section class="panel"><div class="panel-head"><h2>這張工單的依據</h2><span class="badge">本機保存</span></div><div class="definition"><span>必要資格</span><b>${p.cert}</b></div><div class="definition"><span>工程師</span><b>${esc(t.engineer||'待指派')}</b></div><div class="definition"><span>來源版本</span><b>${p.source} · v${p.version}</b></div><div class="definition"><span>異常條件</span><b>${esc(t.conditions)}</b></div><button class="text-button" data-source="${t.plan}">核對來源原文 ↗</button><div class="info-note">這是展示流程，來源與紀錄為虛構資料。角色切換不構成正式帳號或權限控制。</div></section><section class="panel"><div class="panel-head"><h2>操作歷程</h2><span class="muted">${t.history.length} 筆</span></div><ol class="history">${[...t.history].reverse().map(h=>`<li>${esc(h.text)}<small>${esc(h.at)}</small></li>`).join('')}</ol>${t.submissions.map((s,i)=>`<details><summary class="text-button">第 ${i+1} 次提交快照 · ${esc(s.at)}</summary><div class="review-evidence">${s.notes.map(n=>`<div>${esc(n)}</div>`).join('')}<div>${esc(s.summary)}</div><div>驗收：${s.accept.every(a=>a==='pass')?'全部通過':'未通過'}</div></div></details>`).join('')}</section></aside></div>`;}
function openSource(id){const p=plans[id];if(!p)return;$('#source-title').textContent=p.title;$('#source-content').innerHTML=`<p class="source-meta">${p.source} · v${p.version} · ${p.section}</p><p>適用範圍：${p.scope}</p><div class="info-note warning">原創虛構手冊摘要，僅用於流程展示，不作為現場操作或復機依據。</div><h3>§ 2 · 排查紀錄</h3><ol>${p.steps.map(s=>`<li>${s[0]}：${s[1]}</li>`).join('')}</ol><h3>§ 3 · 驗收紀錄</h3><p>${p.quote}</p><ol>${p.accept.map(a=>`<li>${a}。</li>`).join('')}</ol>`;$('#source-dialog').showModal();}
function openNew(){if(!roleIs('supervisor'))return;$('#new-form').reset();$('#new-dialog').showModal();}
function action(name){const t=activeTicket();if(name==='new')return openNew();if(name==='scenario'){if(!roleIs('supervisor'))return;const existing=state.tickets.find(x=>x.plan==='atc'&&x.stage<4);if(existing)return goto('ticket/'+existing.id);const next=makeTicket('CNC-03','換刀卡住，只發生在 12 號刀位','ATC-07',2,'其他刀位正常，氣壓 0.48 MPa。');state.tickets.unshift(next);save();return goto('ticket/'+next.id);}if(name==='switch-engineer'||name==='switch-supervisor'){state.role=name==='switch-engineer'?(t?.engineer==='王志明'?'engineer-wang':'engineer'):'supervisor';save();return render();}if(!t)return;
  if(name==='approve'){if(t.stage!==0||!roleIs('supervisor'))return;if(!$('#source-confirm').checked)return toast('請先勾選已核對來源與適用性。');t.stage=1;log(t,'林組長核准排查與驗收清單 · '+plans[t.plan].source+' v1.0');render();}
  if(name==='sample'){if(t.stage!==2||!roleIs('engineer')||t.engineer!==engineerName())return;t.checks=[true,true,true];t.notes=[...plans[t.plan].sample];t.accept=['pass','pass'];t.summary=plans[t.plan].label+'展示異常已排除；已完成排查，所有展示復測項目通過。';save();render();toast('已填入虛構紀錄，可修改驗收為「失敗」測試阻擋。');}
  if(name==='return'){if(t.stage!==3||!roleIs('supervisor'))return;const note=$('#review-note').value.trim();if(note.length<3)return toast('退回重修前，請填寫至少 3 字的具體原因。');t.review=note;t.stage=2;t.rework=true;t.checks=[false,false,false];t.notes=['','',''];t.accept=['',''];t.summary='';log(t,'林組長退回重修：'+note);render();toast('已退回；前次提交快照仍保留。');}
  if(name==='complete'){if(t.stage!==3||!roleIs('supervisor'))return;t.review=$('#review-note').value.trim()||'已核對排查紀錄及復測結果，通過展示驗收。';t.stage=4;log(t,'林組長通過審核並結案：'+t.review);render();toast('工單已完成，可核對並發布案例。');}
  if(name==='publish'){if(t.stage!==4||t.published||!roleIs('supervisor'))return;const title=$('#case-title').value.trim(),summary=$('#case-summary').value.trim();if(title.length<3||summary.length<5)return toast('請填寫案例標題與至少 5 字的摘要。');if(!$('#case-confirm').checked)return toast('請先勾選主管已核對內容與來源。');state.cases.unshift({title,summary,machine:t.machine,source:plans[t.plan].source,ticket:t.id,at:stamp()});t.published=true;log(t,'林組長核對並發布維修案例');render();toast('案例已發布，保存在此瀏覽器。');}
}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-ticket]').forEach(b=>b.onclick=()=>goto('ticket/'+b.dataset.ticket));document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>openSource(b.dataset.source));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});document.querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>{const t=activeTicket(),p=people[Number(b.dataset.assign)];if(!t||t.stage!==1||!roleIs('supervisor'))return;if(!eligible(p,t))return toast('資格、出勤或容量不符合，無法派工。');t.engineer=p.name;t.stage=2;log(t,'林組長指派 '+p.name+' · 保留 '+t.hours+' 小時展示容量');render();toast('已指派，切換為工程師開始排查。');});
 const search=$('#source-search');if(search)search.oninput=()=>{const q=search.value.trim().toLowerCase();$('#source-results').innerHTML=Object.values(plans).filter(p=>[p.source,p.title,p.scope,p.alarm,p.quote].join(' ').toLowerCase().includes(q)).map(sourceCard).join('')||'<p class="empty">找不到符合條件的示範來源。</p>';document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>openSource(b.dataset.source));};
 const form=$('#execution-form');if(form){const t=activeTicket();form.oninput=e=>{if(!isEngineer()||t.engineer!==engineerName()||t.stage!==2)return;const el=e.target;if(el.dataset.check!==undefined)t.checks[+el.dataset.check]=el.checked;if(el.dataset.note!==undefined)t.notes[+el.dataset.note]=el.value;if(el.dataset.accept!==undefined)t.accept[+el.dataset.accept]=el.value;if(el.id==='summary')t.summary=el.value;save();$('#validation').textContent=validationText(t);$('#validation').classList.toggle('warning',t.accept.includes('fail'));};form.onsubmit=e=>{e.preventDefault();if(t.stage!==2||!roleIs('engineer')||t.engineer!==engineerName())return;if(!ready(t))return toast(t.accept.includes('fail')?'驗收失敗，無法提交；請修復後重新復測。':'請完成所有排查紀錄、驗收通過與修復摘要。');t.submissions.push({at:stamp(),notes:[...t.notes],accept:[...t.accept],summary:t.summary,source:plans[t.plan].source});t.stage=3;t.rework=false;log(t,engineerName()+'提交排查紀錄與復測結果 · 驗收全部通過');render();toast('已提交，等待主管審核。');};}
}
function render(){const view=currentView();$('#desktop-nav').innerHTML=navHTML(view);$('#mobile-nav').innerHTML=navHTML(view);$('#role').value=state.role;$('#role-avatar').textContent=state.role==='supervisor'?'主':engineerName().slice(0,1);$('#breadcrumb').textContent=(navs.find(n=>n[0]===view)||['','維修工單'])[1];$('#main').innerHTML=view==='tickets'?ticketsView():view==='sources'?sourcesView():view==='cases'?casesView():view==='ticket'?ticketView(activeTicket()):overview();bind();}
$('#role').onchange=e=>{state.role=e.target.value;save();render();toast('已切換為'+(state.role==='supervisor'?'主管 · 林組長':'工程師 · '+engineerName()));};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());
$('#new-form').onsubmit=e=>{e.preventDefault();if(!roleIs('supervisor'))return;const data=new FormData(e.target),issue=String(data.get('issue')).trim(),conditions=String(data.get('conditions')).trim(),alarm=String(data.get('alarm')).trim(),hours=Number(data.get('hours'));if(issue.length<5||!conditions||!alarm||!Number.isFinite(hours)||hours<.5||hours>8)return toast('請填寫完整條件，估時需介於 0.5–8 小時。');const text=issue+' '+alarm;const plan=/換刀|刀位|刀庫|卡刀|ATC/i.test(text)?'atc':/主軸|過熱|振動|E102/i.test(text)?'spindle':/冷卻|泵浦|COOL/i.test(text)?'coolant':null;if(!plan)return toast('這版 demo 支援換刀、主軸、冷卻情境，請選擇其中一種異常。');const t=makeTicket(String(data.get('machine')),issue,alarm,hours,conditions,plan);state.tickets.unshift(t);save();$('#new-dialog').close();goto('ticket/'+t.id);toast('工單已建立，請核對示範來源。');};
$('#reset').onclick=()=>$('#reset-dialog').showModal();$('#confirm-reset').onclick=()=>{state=seed();filter='全部';save();$('#reset-dialog').close();goto('overview');toast('已恢復原始展示資料。');};
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
save();render();
